  isJSXWhitespaceExpression,
  isJSXNode,
  isMeaningfulJSXText,
  matchJsxWhitespaceRegex,
  rawText,
  isLiteral,
  isCallOrOptionalCallExpression,
  isStringLiteral,
  isBinaryish,
  hasComment,
  CommentCheckFlags,
